mapper.select:
SELECT e.*, s.school_name AS school_name, g.grade_name AS grade_name, CASE e.type WHEN 1 THEN '期中考试' WHEN 2 THEN '期末考试' WHEN 3 THEN '月考' WHEN 4 THEN '模拟考试' ELSE '其他' END AS type_name, CASE e.status WHEN 0 THEN '草稿' WHEN 1 THEN '待考试' WHEN 2 THEN '考试中' WHEN 3 THEN '阅卷中' WHEN 4 THEN '已完成' WHEN 5 THEN '已发布' ELSE '未知状态' END AS status_name, (SELECT COUNT(1) FROM exam_subject es WHERE es.exam_id = e.id AND es.deleted = 0) AS subject_count FROM exam e LEFT JOIN school s ON s.id = e.school_id LEFT JOIN grade g ON g.id = e.grade_id WHERE e.deleted = 0
AND e.school_id = #{query.schoolId}
AND e.name LIKE CONCAT('%', #{query.name}, '%')
AND e.type = #{query.type}
AND e.academic_year = #{query.academicYear}
AND e.semester = #{query.semester}
AND e.grade_id = #{query.gradeId}
AND e.status = #{query.status}
ORDER BY e.create_time DESC
